/* 要素非表示（IDセレクタのdisplay指定より優先させるため!important） */
.axpc_NONE {
    display: none !important;
}

/* 要素非表示（レイアウト変更なし） */
.axpc_HIDDEN {
    visibility: hidden;
}

/* テキスト縁取り */
.axpc_text_border {
    text-shadow:
        black 2px 0px, black -2px 0px,
        black 0px -2px, black 0px 2px,
        black 2px 2px, black -2px 2px,
        black 2px -2px, black -2px -2px,
        black 1px 2px, black -1px 2px,
        black 1px -2px, black -1px -2px,
        black 2px 1px, black -2px 1px,
        black 2px -1px, black -2px -1px;
    /*
    text-shadow: 1px 1px 0 #000, -1px -1px 0 #000,
        -1px 1px 0 #000, 1px -1px 0 #000,
        0px 1px 0 #000, 0-1px 0 #000,
        -1px 0 0 #000, 1px 0 0 #000;
    */
}

/* キャンバスの透過メッシュ */
.axpc_background_mesh {
    background: rgb(204, 204, 204);
    background-image: repeating-conic-gradient(from 0deg, transparent 0deg 90deg, #fff 90deg 180deg);
    background-size: 16px 16px;
    background-position: 0 0, 8px 8px, 8px 8px, 16px 16px;
}

/* サブウィンドウ共通 */
.axpc_subwindow {
    touch-action: none;
    -webkit-user-select: none;
    user-select: none;
    position: absolute;
    z-index: 2000;
    left: 0;
    top: 0;
    height: 100%;
    width: 100%;
    overflow: hidden;
    background-color: rgba(0, 0, 0, 0);
}

.axpc_subwindow>div {
    background-color: #333;
    color: #fff;
    border-color: #000;
    border-style: solid;
    border-width: 2px;
    border-color: #aaa;
    box-shadow: 4px 4px 8px #777;
    border-radius: 5px;
    width: 188px;
    height: auto;
    padding: 8px;
}

/* 色作成 補助線設定のカラー選択枠 */
.axpc_colorRect {
    height: 32px;
    width: 32px;
    cursor: pointer;
    border-radius: 5px;
    margin: 1px;
    border-width: 2px;
    border-style: solid;
    border-color: #aaa;
}

/* オーバーレイ操作子共通（キャンバス上に浮かぶUI部品） */
.axpc_overlay_knob,
.axpc_overlay_btn {
    position: absolute;
    width: 40px;
    height: 40px;
    z-index: 3000;
    border-radius: 8px;
    background-color: var(--axp-knob-bg, rgba(85, 85, 85, 0.85));
    background-repeat: no-repeat;
    background-position: center;
    background-size: 26px 26px;
    touch-action: none;
    user-select: none;
}

/* オーバーレイノブ（ドラッグ操作用） */
.axpc_overlay_knob {
    border: 3px solid var(--axp-knob-border, #eee);
    cursor: grab;
}

.axpc_overlay_knob:active {
    cursor: all-scroll;
    background-color: rgba(0, 0, 0, 0.85);
}

/* オーバーレイボタン（タップ操作用） */
.axpc_overlay_btn {
    border: 2px solid var(--axp-btn-border, #ccc);
    cursor: pointer;
    padding: 0;
    appearance: none;
}

.axpc_overlay_btn:focus-visible {
    outline: 2px solid var(--axp-border-focus, #8bd3ff);
    outline-offset: 2px;
}

.axpc_overlay_btn:active {
    background-color: rgba(0, 0, 0, 0.85);
}
