___CSS_LOADER_EXPORT___.push([module.id, `/* 補助ツール */

#axp_tool {
    width: 300px;
}

.axpc_tool_shell {
    display: flex;
    gap: var(--axp-sp-3);
}

/* 補助ツール左側 */
#axp_tool_div_leftSide {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;
    align-content: flex-start;
}

.axpc_tool_controlDeck {
    gap: 2px;
}

/* キャンバスサイズ表示ラベル */
#axp_tool_div_canvasSize {
    text-align: center;
}

/* キャンバスサイズ文字 */
#axp_tool_span_canvasSize {
    font-size: 13px;
}

/* サムネイル表示の外枠 */
#axp_tool_div_minimap_outer {
    cursor: grab;
    position: relative;
    width: 132px;
    height: 132px;
    margin-right: 4px;
    margin-top: 2px;
    margin-bottom: 4px;
    border: 6px solid #888;
}

/* サムネイル表示の内枠 */
#axp_tool_div_minimap_inner {
    width: 120px;
    height: 120px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #777;
}

/* キャンバスが画面をはみ出た時に、サムネイルに表示する赤線 */
#axp_tool_div_minimap_line {
    position: absolute;
    border: 2px #f00 solid;
}

/* 補助ツール右側 */
.axpc_tool_actionGrid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-content: start;
    gap: 4px;
    margin-top: 2px;
    margin-left: 0;
    min-width: 146px;
}

/* 100% */
#axp_tool_button_loupeReset {
    width: 62px;
    margin: 0 5px 0 1px;
}

/* 拡大縮小（＋－） */
#axp_tool_button_loupeUp,
#axp_tool_button_loupeDown {
    width: 30px;
    margin-right: 4px;
}

/* 復元 */
#axp_tool_button_restore {
    width: 100%
}

/* キャンバスサイズ・プリセット */
#axp_tool_div_canvasSizePreset {
    display: flex;
    gap: 3px;
    margin: 2px 0 4px;
}

.axpc_tool_sizePreset {
    flex: 1;
    min-width: 0;
    padding: 3px 0;
    font-size: 11px;
}

/* この環境の上限を超えるプリセットの無効表示（ダブルクリック編集は可能） */
.axpc_tool_sizePreset.axpc_tool_sizePreset_disabled {
    opacity: 0.4;
}

/* 背景色トグル（肌色/白） */
#axp_tool_div_bgColor {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 2px 0 4px;
}

#axp_tool_span_bgColorLabel {
    font-size: 12px;
}

#axp_tool_toggle_bgColor::after {
    content: attr(data-label);
}

/* 書出し・共有 / 参照画像 disclosure */
.axp_tool_disclosure {
    --axp-interop-compact-h: 22px;

    display: flex;
    flex-direction: column;
    gap: 2px;
    width: 132px;
    margin: 2px 4px 4px 0;
    padding: 3px;
    border: 1px solid rgba(255, 255, 255, .08);
    border-radius: var(--axp-r-lg);
    background: var(--axp-surface-panel);
    font-size: 11px;
    box-sizing: border-box;
}

.axp_tool_disclosureToggle {
    display: flex;
    align-items: center;
    gap: 4px;
    box-sizing: border-box;
    width: 100%;
    min-height: 26px;
    padding: 3px 5px;
    border: 1px solid var(--axp-border-soft);
    border-radius: var(--axp-r-md);
    color: inherit;
    background: rgba(255, 255, 255, .08);
    line-height: 1.1;
    text-align: left;
    cursor: pointer;
}

.axp_tool_disclosureToggle::before {
    content: "▸";
    display: inline-block;
    flex: 0 0 auto;
    transform-origin: 50% 50%;
    transition: transform .12s ease;
}

.axp_tool_disclosureToggle[aria-expanded="true"]::before {
    transform: rotate(90deg);
}

#axp_tool_button_timelapse,
#axp_tool_button_clipboardCopy,
#axp_tool_button_psdExport,
#axp_tool_button_referenceLoad,
#axp_tool_button_referenceRemove {
    box-sizing: border-box;
    width: 100%;
    min-height: 24px;
    line-height: 1.1;
    padding-right: 3px;
    padding-left: 3px;
}

#axp_tool_button_timelapse[data-recording="true"]::before {
    content: "● ";
}

.axp_tool_disclosurePanel {
    display: flex;
    flex-direction: column;
    gap: 2px;
    box-sizing: border-box;
    margin-left: 5px;
    padding-left: 7px;
    border-left: 2px solid var(--axp-accent-border);
}

.axp_tool_disclosurePanel[hidden] {
    display: none;
}

#axp_tool_div_referenceDetails {
    display: grid;
    gap: 2px;
    box-sizing: border-box;
    padding: 3px;
    border: 1px solid var(--axp-border-soft);
    border-radius: var(--axp-r-md);
    background: var(--axp-surface-panel-strong);
}

#axp_tool_div_referenceDetails[hidden] {
    display: none;
}

#axp_tool_file_reference {
    display: none;
}

#axp_tool_div_referenceDetails label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 3px;
    box-sizing: border-box;
    min-width: 0;
    height: var(--axp-interop-compact-h);
    font-size: 10.5px;
    white-space: nowrap;
}

.axp_tool_referenceInline {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 2px;
    align-items: center;
}

#axp_tool_div_referenceToggles label {
    justify-content: flex-start;
}

#axp_tool_div_referenceToggles input[type="checkbox"] {
    margin: 0 2px 0 0;
}

#axp_tool_div_referencePosition label {
    gap: 1px;
    font-size: 10px;
}

#axp_tool_div_referenceDetails input[type="number"] {
    width: 32px;
    height: 20px;
    box-sizing: border-box;
    padding: 0 1px;
    font-size: 10px;
}

#axp_tool_div_referenceDetails .axpc_range {
    box-sizing: border-box;
    flex: 0 0 72px;
    width: 72px;
    height: 18px;
    overflow: hidden;
    border-radius: 5px;
}

#axp_tool_div_referenceDetails .axpc_range input[type="range"] {
    width: 72px;
    height: 18px;
    border: 2px solid #444;
    border-radius: 5px;
}

#axp_tool_div_referenceDetails .axpc_range input[type="range"]::-webkit-slider-thumb {
    width: 18px;
    height: 18px;
    border: 3px solid #777;
    border-radius: 5px;
    box-shadow: -72px 0 0 72px #777;
}

#axp_tool_div_referenceDetails .axpc_range input[type="range"]::-moz-range-track {
    height: 18px;
}

#axp_tool_div_referenceDetails .axpc_range input[type="range"]::-moz-range-thumb {
    width: 18px;
    height: 18px;
    border: 3px solid #777;
    border-radius: 5px !important;
    box-shadow: -72px 0 0 72px #777;
}

.axp_tool_disclosure button:focus-visible,
#axp_tool_div_referenceDetails input:focus-visible {
    outline: 2px solid var(--axp-border-focus);
    outline-offset: 1px;
}

@media (pointer: coarse) {
    .axp_tool_disclosure {
        gap: 6px;
    }

    .axp_tool_disclosureToggle,
    #axp_tool_button_timelapse,
    #axp_tool_button_clipboardCopy,
    #axp_tool_button_psdExport,
    #axp_tool_button_referenceLoad,
    #axp_tool_button_referenceRemove {
        min-height: 44px;
    }

    #axp_tool_div_referenceDetails label {
        min-height: 44px;
    }

    #axp_tool_div_referenceDetails input[type="checkbox"] {
        min-width: 24px;
        min-height: 24px;
    }

    #axp_tool_div_referenceDetails label {
        height: auto;
    }

    #axp_tool_div_referenceDetails .axpc_range,
    #axp_tool_div_referenceDetails .axpc_range input[type="range"] {
        height: 28px;
    }

    #axp_tool_div_referenceDetails .axpc_range input[type="range"]::-webkit-slider-thumb {
        width: 28px;
        height: 28px;
    }

    #axp_tool_div_referenceDetails .axpc_range input[type="range"]::-moz-range-thumb {
        width: 28px;
        height: 28px;
    }
}

/* セーブ ロード 左右反転 上下反転 背景透過 補助線の枠 */
#axp_tool_button_save,
#axp_tool_button_load,
#axp_tool_button_flipH,
#axp_tool_button_flipV,
#axp_tool_button_transparent,
#axp_tool_div_gridbutton {
    width: 100%;
}

/* 補助線ボタン枠 */
#axp_tool_div_gridbutton {
    display: flex;
}

/* 補助線 */
#axp_tool_button_grid {
    flex: 1;
    min-width: 0;
}

/* 補助線設定（歯車アイコン） */
#axp_tool_button_gridConfig {
    isolation: isolate;
    height: 100%;
    width: 24px;
    background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
    background-position: 0% 50%;
    background-repeat: no-repeat;
}

/* 補助線設定UI */
#axp_tool_div_gridConfig {
    padding: 4px 0;
}

#axp_tool_div_gridConfig>div {
    display: flex;
    column-gap: 8px;
}

/* 右側のスライダーコンテナ */
#axp_tool_div_gridConfig>div>div:nth-of-type(2) {
    display: flex;
    padding-top: 4px;
}

/* 補助線：表示ボタンなど用コンテナ */
.axpc_tool_div_gridConfigButton {
    display: flex;
    border: 2px solid #555;
    border-radius: 8px;
    column-gap: 8px;
    margin-bottom: 2px;
}

/* 主線などのラベル */
.axpc_tool_div_gridConfigButton>div:nth-of-type(1) {
    display: flex;
    align-items: center;
    justify-content: center;
    background: #666;
    width: 50px;
}

/* px指定テキストボックス */
#axp_tool_number_gridPixel1,
#axp_tool_number_gridPixel2 {
    border-radius: 5px;
    width: 60px;
    height: 32px;
    font-family: "Arial Black", Arial, sans-serif;
    padding-left: 2px;
}

/* 補助線の色変更サブメニュー */
/* 不透明度 */
#axp_gridconfig_range_gridColor {
    width: 100% !important;
}
